// Modified pushScope method to potentially address scoped aliases bug
void pushScope(Scope scope) {
    Scope parent = scope.getParentScope();
    if (parent != null) {
        if (parent != currentScope)
            codeBug();
    } else {
        currentScope.addChildScope(scope);
    }
    currentScope = scope;
}

public Scope getScope() {
        Node current = this;
        while (current != null) {
            if (current instanceof Scope) {
                return (Scope) current;
            }
            current = current.getParent();
        }
        return null;
    }

